var t=`0989-injo-gogi-bap`;var o=`world-0989`;var n=`KP`;var a=`east-asia`;var r=4;var s=92;var l={en:`Injo Gogi Bap`,ua:`Інчо коги бап`};var d={en:`Injo Gogi Bap is a North Korea dish made with textured soy protein, light soy sauce, garlic, yellow onion. This home-scale recipe assigns measured ingredients to the steps where they are used. Home adaptation using hydrated textured soy protein; traditionally prepared injo gogi has a different texture and shape.`,ua:`Інчо коги бап, страва кухні країни Північна Корея. Основні складники: текстурований соєвий білок, світлий соєвий соус, часник, жовта цибуля. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів. Домашня адаптація з розмоченого соєвого текстурату; традиційний інчо коги має іншу форму й текстуру.`};var g=[{en:`Hydrate dry textured soy protein in clean hot drinking water until supple, drain and squeeze thoroughly before seasoning.`,ua:`Замочіть сухий соєвий текстурат у чистій гарячій питній воді до м’якості, злийте й ретельно відтисніть перед приправленням.`,t:[`soaking-legumes`],m:40,i:[[`textured-soy-protein`,300,`g`],[`water`,650,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`light-soy-sauce`,60,`ml`],[`garlic`,4,`clove`],[`gochugaru`,6,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 14 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 14 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:14,i:[[`canola-oil`,45,`ml`],[`yellow-onion`,175,`g`]]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 24 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 24 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:24,i:[[`calrose-rice`,380,`g`],[`water`,730,`ml`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:6,i:[[`kimchi`,200,`g`]]}];var u={slug:t,id:o,country:`KP`,region:a,servings:4,minutes:92,title:l,text:d,steps:g};export{n as country,u as default,o as id,s as minutes,a as region,r as servings,t as slug,g as steps,d as text,l as title};